import empty = require( '@stdlib/ndarray/base/empty' );
import swapDimensions = require( './index' );


// TESTS //

// The function returns an ndarray...
{
	const order = 'row-major';
	const sh = [ 2, 2 ];

	swapDimensions( empty( 'float64', sh, order ), [ 0, 1 ], false ); // $ExpectType float64ndarray
	swapDimensions( empty( 'float32', sh, order ), [ 0, 1 ], false ); // $ExpectType float32ndarray
	swapDimensions( empty( 'complex128', sh, order ), [ 0, 1 ], false ); // $ExpectType complex128ndarray
	swapDimensions( empty( 'complex64', sh, order ), [ 0, 1 ], false ); // $ExpectType complex64ndarray
	swapDimensions( empty( 'int32', sh, order ), [ 0, 1 ], false ); // $ExpectType int32ndarray
	swapDimensions( empty( 'int16', sh, order ), [ 0, 1 ], false ); // $ExpectType int16ndarray
	swapDimensions( empty( 'int8', sh, order ), [ 0, 1 ], false ); // $ExpectType int8ndarray
	swapDimensions( empty( 'uint32', sh, order ), [ 0, 1 ], false ); // $ExpectType uint32ndarray
	swapDimensions( empty( 'uint16', sh, order ), [ 0, 1 ], false ); // $ExpectType uint16ndarray
	swapDimensions( empty( 'uint8', sh, order ), [ 0, 1 ], false ); // $ExpectType uint8ndarray
	swapDimensions( empty( 'uint8c', sh, order ), [ 0, 1 ], false ); // $ExpectType uint8cndarray
}

// The compiler throws an error if the function is provided a first argument which is not an ndarray...
{
	swapDimensions( '10', [ 0, 1 ], false ); // $ExpectError
	swapDimensions( 10, [ 0, 1 ], false ); // $ExpectError
	swapDimensions( false, [ 0, 1 ], false ); // $ExpectError
	swapDimensions( true, [ 0, 1 ], false ); // $ExpectError
	swapDimensions( null, [ 0, 1 ], false ); // $ExpectError
	swapDimensions( [], [ 0, 1 ], false ); // $ExpectError
	swapDimensions( {}, [ 0, 1 ], false ); // $ExpectError
	swapDimensions( ( x: number ): number => x, [ 0, 1 ], false ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a collection of numbers...
{
	const x = empty( 'float64', [ 2, 2 ], 'row-major' );

	swapDimensions( x, '5', false ); // $ExpectError
	swapDimensions( x, true, false ); // $ExpectError
	swapDimensions( x, false, false ); // $ExpectError
	swapDimensions( x, null, false ); // $ExpectError
	swapDimensions( x, undefined, false ); // $ExpectError
	swapDimensions( x, [ '5' ], false ); // $ExpectError
	swapDimensions( x, {}, false ); // $ExpectError
	swapDimensions( x, ( x: number ): number => x, false ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a boolean...
{
	const x = empty( 'float64', [ 2, 2 ], 'row-major' );

	swapDimensions( x, [ 0, 1 ], '5' ); // $ExpectError
	swapDimensions( x, [ 0, 1 ], 5 ); // $ExpectError
	swapDimensions( x, [ 0, 1 ], null ); // $ExpectError
	swapDimensions( x, [ 0, 1 ], undefined ); // $ExpectError
	swapDimensions( x, [ 0, 1 ], [ '5' ] ); // $ExpectError
	swapDimensions( x, [ 0, 1 ], {} ); // $ExpectError
	swapDimensions( x, [ 0, 1 ], ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = empty( 'float64', [ 2, 2 ], 'row-major' );

	swapDimensions( x ); // $ExpectError
	swapDimensions( x, [ 0, 1 ] ); // $ExpectError
	swapDimensions( x, [ 0, 1 ], false, {} ); // $ExpectError
}
